import "dotenv/config"
import { env } from "./env"
import { loadOpenApiSpec } from "./openapi-loader"
import { createMcpServer } from "./server/create-mcp-server"
import { runSseServer } from "./server/sse-server"
import { runStdioServer } from "./server/stdio-server"

async function main() {
  await loadOpenApiSpec()

  if (env.OPENMEERKAT_MCP_TRANSPORT === "both") {
    await Promise.all([
      runStdioServer(createMcpServer),
      runSseServer(createMcpServer),
    ])
    return
  }

  if (env.OPENMEERKAT_MCP_TRANSPORT === "sse") {
    await runSseServer(createMcpServer)
    return
  }

  await runStdioServer(createMcpServer)
}

main().catch((error) => {
  console.error("Fatal error in main():", error)
  process.exit(1)
})

import { env } from "./env"

interface OpenAPISpec {
  paths?: Record<string, Record<string, OpenAPIOperation>>
  servers?: Array<{ url: string }>
}

interface OpenAPIOperation {
  description?: string
  operationId?: string
  parameters?: OpenAPIParameter[]
  requestBody?: {
    required?: boolean
    content?: {
      "application/json"?: {
        schema?: OpenAPISchemaObject
      }
    }
  }
  summary?: string
}

interface OpenAPIParameter {
  description?: string
  in: "path" | "query" | "header" | "cookie"
  name: string
  required?: boolean
  schema?: OpenAPISchemaObject
}

interface OpenAPISchemaObject {
  allOf?: OpenAPISchemaObject[]
  anyOf?: OpenAPISchemaObject[]
  default?: unknown
  description?: string
  enum?: unknown[]
  format?: string
  items?: OpenAPISchemaObject
  nullable?: boolean
  oneOf?: OpenAPISchemaObject[]
  properties?: Record<string, OpenAPISchemaObject>
  required?: string[]
  type?: string
}

export interface DynamicTool {
  baseUrl: string
  bodyParamNames: string[]
  description: string
  inputSchema: {
    type: "object"
    properties: Record<string, unknown>
    required?: string[]
  }
  method: string
  name: string
  pathParamNames: string[]
  pathTemplate: string
  queryParamNames: string[]
}

let cachedTools: DynamicTool[] | null = null

const HTTP_METHODS = new Set(["get", "post", "put", "patch", "delete"])

function toSnakeCase(str: string): string {
  return str
    .replace(/([A-Z]{2,})(?=[A-Z][a-z]|$)/g, "_$1")
    .replace(/([a-z\d])([A-Z])/g, "$1_$2")
    .toLowerCase()
    .replace(/[.\-\s]+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_|_$/g, "")
}

function extractPathParamNames(pathTemplate: string): string[] {
  const matches = pathTemplate.match(/\{([^}]+)\}/g)
  return matches ? matches.map((m) => m.slice(1, -1)) : []
}

function buildInputSchema(operation: OpenAPIOperation): {
  schema: DynamicTool["inputSchema"]
  bodyParamNames: string[]
  queryParamNames: string[]
} {
  const properties: Record<string, unknown> = {}
  const required: string[] = []
  const bodyParamNames: string[] = []
  const queryParamNames: string[] = []

  for (const param of operation.parameters ?? []) {
    if (param.in !== "path" && param.in !== "query") {
      continue
    }
    const schema: Record<string, unknown> = {
      ...(param.schema ?? { type: "string" }),
    }
    if (param.description) {
      schema.description = param.description
    }
    properties[param.name] = schema
    if (param.required || param.in === "path") {
      required.push(param.name)
    }
    if (param.in === "query") {
      queryParamNames.push(param.name)
    }
  }

  const bodySchema =
    operation.requestBody?.content?.["application/json"]?.schema
  if (bodySchema?.properties) {
    for (const [key, value] of Object.entries(bodySchema.properties)) {
      properties[key] = value
      bodyParamNames.push(key)
    }
    for (const key of bodySchema.required ?? []) {
      if (!required.includes(key)) {
        required.push(key)
      }
    }
  }

  return {
    schema: {
      type: "object",
      properties,
      ...(required.length > 0 ? { required } : {}),
    },
    bodyParamNames,
    queryParamNames,
  }
}

export async function loadOpenApiSpec(): Promise<DynamicTool[]> {
  if (cachedTools !== null) {
    return cachedTools
  }

  const specUrl = `${env.OPENMEERKAT_API_URL}/public-spec.json`

  const response = await fetch(specUrl, {
    headers: { Accept: "application/json" },
  })

  if (!response.ok) {
    throw new Error(
      `Failed to fetch OpenAPI spec from ${specUrl}: ${response.status} ${response.statusText}`,
    )
  }

  const spec = (await response.json()) as OpenAPISpec
  const baseUrl = spec.servers?.[0]?.url ?? env.OPENMEERKAT_API_URL
  const tools: DynamicTool[] = []

  for (const [pathTemplate, pathItem] of Object.entries(spec.paths ?? {})) {
    for (const [httpMethod, operation] of Object.entries(pathItem)) {
      if (!HTTP_METHODS.has(httpMethod)) {
        continue
      }
      if (!operation.operationId) {
        continue
      }

      const pathParamNames = extractPathParamNames(pathTemplate)
      const { schema, bodyParamNames, queryParamNames } =
        buildInputSchema(operation)

      tools.push({
        name: toSnakeCase(operation.operationId),
        description:
          operation.summary ?? operation.description ?? operation.operationId,
        inputSchema: schema,
        baseUrl,
        pathTemplate,
        method: httpMethod.toUpperCase(),
        pathParamNames,
        bodyParamNames,
        queryParamNames,
      })
    }
  }

  cachedTools = tools
  // stderr keeps this out of the stdio MCP transport stream
  console.error(`Loaded ${tools.length} tools from OpenAPI spec`)
  return tools
}

export function getCachedTools(): DynamicTool[] {
  return cachedTools ?? []
}

import "dotenv/config"
import { loadOpenApiSpec } from "./openapi-loader"

async function testTools() {
  console.log("🧪 Testing MCP Server Tools...\n")

  const tools = await loadOpenApiSpec()

  console.log(`✅ Loaded ${tools.length} tools from OpenAPI spec:\n`)
  for (const tool of tools) {
    const paramCount = Object.keys(tool.inputSchema.properties).length
    console.log(`  • ${tool.name} (${paramCount} params) — ${tool.description}`)
  }
}

testTools().catch(console.error)

import type {
  AIAgentModel,
  ConversationModel,
} from "@openmeerkat/database/types"
import { type ModelMessage, streamText } from "ai"
import { beforeEach, describe, expect, test, vi } from "vitest"

const state = {
  aiResponseText: "Hello from AI",
}

const appendHistoryMock = vi.hoisted(() => vi.fn(async () => undefined))
const createAIModelInstanceMock = vi.hoisted(() =>
  vi.fn(() => ({ type: "native-model" })),
)
const createOpenaiCompatibleModelInstanceMock = vi.hoisted(() =>
  vi.fn(() => ({ type: "openai-compatible-model" })),
)
const findAIIntegrationMock = vi.hoisted(() =>
  vi.fn(async () => ({ id: "native-integration" })),
)
const findOpenaiCompatibleMock = vi.hoisted(() => vi.fn())

vi.mock("@openmeerkat/ai", () => ({
  aiTimeouts: { aiTotal: 30_000, aiStep: 10_000, aiChunk: 5000 },
  helpTexts: {
    fallbackLookup: "I found something, but cannot summarize it yet.",
    fileSearchDescription: "Search files",
    fileSearchQueryDescription: "Query",
    fileSearchNoResult: "No result",
    fileSearchFoundPrefix: "Found",
  },
  processStreamingText: vi.fn(async () => ({ fullText: state.aiResponseText })),
  toolPrefixes: { enum: { file: "file", fn: "fn", mcp: "mcp", sys: "sys" } },
}))

vi.mock("@openmeerkat/ai/server", () => ({
  aiContextService: { appendHistory: appendHistoryMock },
  aiIntegrationService: { findBy: findAIIntegrationMock },
  appendFabricationGuard: (prompt: string) => prompt,
  appendKnowledgeBaseGuard: (prompt: string) => prompt,
  appendToolOutputGuard: (prompt: string) => prompt,
  createAIModelInstance: createAIModelInstanceMock,
  createOpenaiCompatibleModelInstance: createOpenaiCompatibleModelInstanceMock,
  getAIToolset: vi.fn(async () => ({ tools: {}, cleanup: vi.fn() })),
  McpClient: vi.fn(),
  normalizeMcpContent: vi.fn((content: unknown) => content),
}))

vi.mock("@openmeerkat/business", () => ({
  integrationOpenaiCompatibleService: {
    findByWorkspaceIdAndId: findOpenaiCompatibleMock,
  },
}))

vi.mock("@openmeerkat/variables", () => ({
  contactVariableService: {
    getAll: vi.fn(async () => []),
    replaceAll: vi.fn(async ({ text }: { text: string }) => text),
  },
}))

vi.mock("ai", () => ({
  streamText: vi.fn(async () => ({ textStream: [] })),
  stepCountIs: vi.fn(() => () => false),
}))

const { runAIAgentRunner } = await import(
  "../src/integration/handlers/shared/ai-agent-runner"
)

function makeAIAgent(overrides?: Partial<AIAgentModel>): AIAgentModel {
  return {
    id: "agent-1",
    workspaceId: "ws-1",
    name: "Test Agent",
    prompt: "You are helpful.",
    messages: [],
    isDefault: false,
    isRichResponse: false,
    tools: [],
    webSearchAuthorizedDomains: [],
    models: [{ provider: "openai", model: "gpt-5.4-mini" }],
    temperature: 0.7,
    maxOutputTokens: 1000,
    createdAt: new Date(),
    updatedAt: new Date(),
    ...overrides,
  } as AIAgentModel
}

function makeConversation(): ConversationModel {
  return {
    id: "conv-1",
    workspaceId: "ws-1",
    contactId: "contact-1",
    channel: "webchat",
    status: "open",
    createdAt: new Date(),
    updatedAt: new Date(),
  } as ConversationModel
}

describe("AI agent runner OpenAI-compatible providers", () => {
  beforeEach(() => {
    vi.clearAllMocks()
    state.aiResponseText = "Hello from AI"
    findOpenaiCompatibleMock.mockResolvedValue({
      id: "dynamic-1",
      autoReply: false,
      enabled: true,
      baseURL: "http://localhost:1234/v1",
      preset: "lmstudio",
      name: "Local",
    })
  })

  test("runs a configured OpenAI-compatible provider row", async () => {
    const result = await runAIAgentRunner({
      aiAgent: makeAIAgent({
        models: [
          {
            kind: "openaiCompatible",
            integrationId: "dynamic-1",
            model: "local-model",
          },
        ] as AIAgentModel["models"],
      }),
      conversation: makeConversation(),
      messages: [] as ModelMessage[],
    })

    expect(result?.provider).toBe("openaiCompatible")
    expect(findOpenaiCompatibleMock).toHaveBeenCalledWith({
      workspaceId: "ws-1",
      id: "dynamic-1",
    })
    expect(createOpenaiCompatibleModelInstanceMock).toHaveBeenCalledWith({
      integration: expect.objectContaining({ id: "dynamic-1" }),
      modelId: "local-model",
    })
    expect(streamText).toHaveBeenCalledWith(
      expect.objectContaining({
        model: { type: "openai-compatible-model" },
      }),
    )
  })

  test("runs a custom OpenAI-compatible provider row", async () => {
    findOpenaiCompatibleMock.mockResolvedValueOnce({
      id: "custom-1",
      autoReply: false,
      enabled: true,
      baseURL: "https://llm.wokushop.com/v1",
      preset: "custom",
      name: "Custom",
    })

    const result = await runAIAgentRunner({
      aiAgent: makeAIAgent({
        models: [
          {
            kind: "openaiCompatible",
            integrationId: "custom-1",
            model: "gpt-4o-mini",
          },
        ] as AIAgentModel["models"],
      }),
      conversation: makeConversation(),
      messages: [] as ModelMessage[],
    })

    expect(result?.provider).toBe("openaiCompatible")
    expect(createOpenaiCompatibleModelInstanceMock).toHaveBeenCalledWith({
      integration: expect.objectContaining({
        id: "custom-1",
        baseURL: "https://llm.wokushop.com/v1",
        preset: "custom",
      }),
      modelId: "gpt-4o-mini",
    })
  })

  test("runs a preferred OpenAI-compatible model without native provider filtering", async () => {
    const result = await runAIAgentRunner({
      aiAgent: makeAIAgent({
        models: [{ provider: "openai", model: "gpt-5.4-mini" }],
      }),
      conversation: makeConversation(),
      messages: [] as ModelMessage[],
      preferredModel: {
        kind: "openaiCompatible",
        integrationId: "dynamic-1",
        model: "local-model",
      },
    })

    expect(result?.provider).toBe("openaiCompatible")
    expect(findOpenaiCompatibleMock).toHaveBeenCalledWith({
      workspaceId: "ws-1",
      id: "dynamic-1",
    })
    expect(createAIModelInstanceMock).not.toHaveBeenCalled()
    expect(createOpenaiCompatibleModelInstanceMock).toHaveBeenCalledWith({
      integration: expect.objectContaining({ id: "dynamic-1" }),
      modelId: "local-model",
    })
  })

  test("skips disabled dynamic providers and continues native fallback", async () => {
    findOpenaiCompatibleMock.mockResolvedValueOnce({
      id: "dynamic-1",
      enabled: false,
    })

    const result = await runAIAgentRunner({
      aiAgent: makeAIAgent({
        models: [
          {
            kind: "openaiCompatible",
            integrationId: "dynamic-1",
            model: "local-model",
          },
          { provider: "openai", model: "gpt-5.4-mini" },
        ] as AIAgentModel["models"],
      }),
      conversation: makeConversation(),
      messages: [] as ModelMessage[],
    })

    expect(result?.provider).toBe("openai")
    expect(createOpenaiCompatibleModelInstanceMock).not.toHaveBeenCalled()
    expect(createAIModelInstanceMock).toHaveBeenCalledWith(
      expect.objectContaining({
        provider: "openai",
        modelId: "gpt-5.4-mini",
      }),
    )
  })
