import { execFileSync } from "node:child_process"
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"
import { afterEach, beforeEach, describe, expect, test } from "vitest"

const SCRIPT = join(
  dirname(fileURLToPath(import.meta.url)),
  "../docker/rootfs/usr/local/bin/docker-entrypoint.sh",
)

// Mirrors the real dist/ layout: one worker*.mjs per tsdown entry, plus a
// `foo` worker that exists in no hardcoded list — proving auto-discovery.
const STANDARD_WORKERS = [
  "chat",
  "events",
  "integration",
  "ai-agent",
  "default",
  "trigger",
  "webhook",
  "schedule",
  "sequence-scheduler",
  "foo",
]

let distDir: string

function touch(path: string): void {
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(path, "")
}

function run(...args: string[]): { stdout: string; status: number } {
  try {
    const stdout = execFileSync("sh", [SCRIPT, ...args], {
      // /bin/echo stub avoids launching node: a resolved `worker <name>` exec
      // simply echoes the script path instead of running it.
      env: { ...process.env, WORKER_DIST_DIR: distDir, NODE_BIN: "/bin/echo" },
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
    })
    return { stdout, status: 0 }
  } catch (error) {
    const err = error as { status?: number; stdout?: string; stderr?: string }
    return {
      stdout: `${err.stdout ?? ""}${err.stderr ?? ""}`,
      status: err.status ?? 1,
    }
  }
}

beforeEach(() => {
  distDir = mkdtempSync(join(tmpdir(), "worker-dist-"))
  for (const w of STANDARD_WORKERS) {
    touch(join(distDir, w, "worker.mjs"))
  }
  touch(join(distDir, "sequence-scheduler", "worker-producer.mjs"))
  touch(join(distDir, "sequence-scheduler", "worker-consumer.mjs"))
})

afterEach(() => {
  rmSync(distDir, { recursive: true, force: true })
})

describe("docker-entrypoint worker discovery", () => {
  test("resolves a standard worker to its dist bundle", () => {
    const { stdout, status } = run("worker", "chat")
    expect(status).toBe(0)
    expect(stdout.trim()).toBe(join(distDir, "chat", "worker.mjs"))
  })

  test("aliases sequence variants to their historical CLI names", () => {
    expect(run("worker", "sequence-producer").stdout.trim()).toBe(
      join(distDir, "sequence-scheduler", "worker-producer.mjs"),
    )
    expect(run("worker", "sequence-consumer").stdout.trim()).toBe(
      join(distDir, "sequence-scheduler", "worker-consumer.mjs"),
    )
  })

  test("auto-discovers a new worker with no script edit", () => {
    const { stdout, status } = run("worker", "foo")
    expect(status).toBe(0)
    expect(stdout.trim()).toBe(join(distDir, "foo", "worker.mjs"))
  })

  test("rejects a worker that was not built (e.g. removed analytics)", () => {
    const { stdout, status } = run("worker", "analytics")
    expect(status).toBe(3)
    expect(stdout).toContain("Usage:")
  })

  test("usage lists discovered workers including events and sequence variants", () => {
    const { stdout } = run("worker", "badname")
    expect(stdout).toContain("events")
    expect(stdout).toContain("sequence-producer")
    expect(stdout).toContain("sequence-consumer")
    // The stale analytics worker must never appear.
    expect(stdout).not.toContain("analytics")
  })

  test("errors when no worker bundles are present", () => {
    rmSync(distDir, { recursive: true, force: true })
    mkdirSync(distDir, { recursive: true })
    const { stdout, status } = run("worker", "all")
    expect(status).toBe(4)
    expect(stdout).toContain("No worker bundles found")
  })
})

import {
  type AIMcpServerAuth,
  aiMcpServerAuthTypes,
} from "@openmeerkat/database/partials"
import ky, { type Options } from "ky"
import { normalizeError } from "universal-error-normalizer"
import { aiTimeouts, helpTexts, mcpConstants } from "../constants"
import { logger } from "../logger"
import {
  type JsonObject,
  type JsonValue,
  type MCPTool,
  mcpContentArraySchema,
  mcpJsonRpcErrorResponseSchema,
  mcpJsonRpcSuccessSchema,
} from "../schemas/mcp"

const mcpKy = ky.create({
  throwHttpErrors: false,
  timeout: aiTimeouts.httpDefault,
  retry: { limit: 0 },
})

export interface McpClientOptions {
  auth: AIMcpServerAuth
  name?: string
  url: string
}

export const normalizeMcpContent = (content: JsonValue): JsonValue => {
  const parsed = mcpContentArraySchema.safeParse(content)
  if (!parsed.success || parsed.data.length === 0) {
    return content
  }

  const firstItem = parsed.data[0]
  if (
    typeof firstItem === "object" &&
    firstItem !== null &&
    "type" in firstItem &&
    firstItem.type === "text" &&
    "text" in firstItem &&
    typeof firstItem.text === "string"
  ) {
    return firstItem.text
  }

  return content
}

export class McpClient {
  private readonly url: string
  private readonly auth: AIMcpServerAuth
  private readonly name: string
  private initialized = false
  private isLegacy = false
  private requestIdCounter = 0

  constructor(options: McpClientOptions) {
    this.url = options.url
    this.auth = options.auth
    this.name = options.name ?? "MCP Server"
  }

  private getNextRequestId(): number {
    this.requestIdCounter = (this.requestIdCounter + 1) % 1_000_000
    return Date.now() + this.requestIdCounter
  }

  private getHeaders(): Record<string, string> {
    const headers: Record<string, string> = {
      Accept: "application/json, text/event-stream",
      "Content-Type": "application/json",
    }

    switch (this.auth.type) {
      case aiMcpServerAuthTypes.enum.header:
        for (const h of this.auth.headers) {
          headers[h.header] = h.value
        }
        break
      case aiMcpServerAuthTypes.enum.token:
        [REDACTED] = `Bearer ${this.auth.token}`
        break
      default:
        break
    }

    return headers
  }

  private async request<T>(
    method: string,
    params: Record<string, unknown> = {},
    timeout?: number,
    isNotification = false,
  ): Promise<T | null> {
    const requestId = isNotification ? undefined : this.getNextRequestId()
    const options: Options = {
      headers: this.getHeaders(),
      json: {
        jsonrpc: helpTexts.jsonRpcVersion,
        ...(requestId === undefined ? {} : { id: requestId }),
        method,
        params,
      },
      timeout: timeout ?? aiTimeouts.httpDefault,
    }

    try {
      const responseText = await mcpKy.post(this.url, options).text()
      if (isNotification) {
        return null
      }
      const trimmed = responseText.trim()
      let parsed: unknown

      if (trimmed.includes("data:")) {
        const dataLines = trimmed
          .split("\n")
          .filter((line: string) => line.startsWith("data:"))
          .map((line: string) => line.slice("data:".length).trim())
        const lastData = dataLines.at(-1) ?? "{}"
        parsed = JSON.parse(lastData)
      } else {
        parsed = JSON.parse(trimmed)
      }

      // Check for JSON-RPC error
      const errorParsed = mcpJsonRpcErrorResponseSchema.safeParse(parsed)
      if (errorParsed.success) {
        throw new Error(errorParsed.data.error.message)
      }

      const successParsed = mcpJsonRpcSuccessSchema.safeParse(parsed)
      if (!successParsed.success) {
        throw new Error("Invalid JSON-RPC 2.0 response")
      }

      return successParsed.data.result as T
    } catch (error) {
      const normalized = normalizeError(error)
      logger.error(
        { error: normalized, method, url: this.url },
        `[McpClient][${this.name}] Request failed`,
      )
      throw error
    }
  }

  private async ensureInitialized() {
    if (!this.initialized) {
      await this.initialize()
    }
  }

  async initialize() {
    if (this.initialized) {
      return
    }

    try {
      await this.request(
        mcpConstants.jsonRpcMethods.initialize,
        {
          protocolVersion: mcpConstants.protocolVersion,
          capabilities: {},
          clientInfo: mcpConstants.clientInfo,
        },
        aiTimeouts.mcpList,
      )

      this.request(
        mcpConstants.jsonRpcMethods.notificationsInitialized,
        {},
        undefined,
        true,
      ).catch((err) => {
        logger.warn(
          { error: normalizeError(err) },
          `[McpClient][${this.name}] Failed to send initialized notification`,
        )
      })

      this.initialized = true
      this.isLegacy = false
    } catch (error) {
      const normalized = normalizeError(error)
      const errorMessage = (normalized.message || "").toLowerCase()
      // JSON-RPC -32601 is typically "Method not found"; avoid broad "not found"/"404"
      // so misconfigured URLs or unrelated errors are not treated as legacy MCP.
      if (errorMessage.includes("method not found")) {
        logger.info(
          { url: this.url, name: this.name },
          `[McpClient][${this.name}] Server does not support initialize, switching to legacy mode`,
        )
        this.isLegacy = true
        this.initialized = true
      } else {
        throw error
      }
    }
  }

  async listTools(): Promise<MCPTool[]> {
    await this.ensureInitialized()

    const result = await this.request<{ tools: MCPTool[] }>(
      mcpConstants.jsonRpcMethods.toolsList,
      {},
      aiTimeouts.mcpList,
    )
    return result?.tools ?? []
  }

  async callTool(toolName: string, args: JsonObject) {
    await this.ensureInitialized()

    const result = await this.request<JsonObject>(
      mcpConstants.jsonRpcMethods.toolsCall,
      {
        name: toolName,
        arguments: args,
      },
      aiTimeouts.mcpCall,
    )

    if (!result) {
      throw new Error(
        `[McpClient][${this.name}] No result returned from tool call: ${toolName}`,
      )
    }

    return {
      isError: false,
      content: result.content as JsonValue,
    }
  }

  getLegacyStatus() {
    return this.isLegacy
  }

  async close() {
    await Promise.resolve()
  }
}

