      contactInbox: baseContactInbox,
    })

    if (!ctx) {
      return {
        status: "error",
        errorMessage: "Integration context not found",
        result: null,
      }
    }

    const imageUrl = await readCustomFieldValue({
      contactId: conversation.contactId,
      customFieldId: step.inputFieldId,
    })

    const inputValidation = editImageInputSchema.safeParse({
      imageUrl: imageUrl ?? "",
      prompt: step.prompt,
      provider: step.provider,
      model: step.model,
      size: step.size,
      quality: step.quality,
    })

    if (!inputValidation.success) {
      logger.warn(
        {
          errors: inputValidation.error.issues,
          conversationId: conversation.id,
        },
        "[ai-edit-image] Invalid input, skipping",
      )
      return {
        status: "error",
        errorMessage: "Invalid input for image edit",
        result: null,
      }
    }

    const aiConfig = await aiIntegrationService.findBy({
      workspaceId: conversation.workspaceId,
      provider: step.provider,
    })

    if (!aiConfig) {
      return {
        status: "error",
        errorMessage: "AI integration not found",
        result: null,
      }
    }

    let model: ImageModel

    try {
      model = createAIImageModelInstance({
        model: aiConfig,
        provider: step.provider,
        modelId: step.model,
      })
    } catch (modelError) {
      logger.warn(
        {
          err: modelError,
          modelId: step.model,
          provider: step.provider,
          conversationId: conversation.id,
        },
        "[ai-edit-image] Failed to create model, attempting fallback",
      )
      if (step.provider === aiProviders.enum.openai) {
        model = createAIImageModelInstance({
          model: aiConfig,
          provider: step.provider,
          modelId: AI_EDIT_IMAGE_FALLBACK_OPENAI_MODEL,
        })
      } else {
        throw new Error(
          `[ai-edit-image] Cannot create image model for provider: ${step.provider}`,
        )
      }
    }

    await assertPublicUrl(inputValidation.data.imageUrl, "image URL")

    const inputImageBuffer = await fetchImageAsBuffer(
      inputValidation.data.imageUrl,
      controller.signal,
    )

    if (inputImageBuffer.length > MAX_IMAGE_BYTES) {
      throw new Error(
        `[ai-edit-image] Input image too large: ${inputImageBuffer.length} bytes`,
      )
    }

    const size =
      step.provider === aiProviders.enum.openai
        ? (step.size as `${number}x${number}`)
        : undefined

    const aspectRatio =
      step.provider === aiProviders.enum.gemini
        ? (step.size as `${number}:${number}`)
        : undefined

    const providerOptions =
      step.provider === aiProviders.enum.openai && step.quality !== "auto"
        ? {
            openai: {
              quality: step.quality === "hd" ? "hd" : "standard",
            },
          }
        : undefined

    const { images } = await generateImage({
      model,
      prompt: {
        images: [inputImageBuffer],
        text: step.prompt,
      },
      size,
      aspectRatio,
      providerOptions,
      abortSignal: controller.signal,
    })

    const image = images[0]
    if (!image) {
      throw new Error("[ai-edit-image] No image returned from provider")
    }

    let buffer: Buffer | null = null

    if (image.uint8Array && image.uint8Array.byteLength > 0) {
      buffer = Buffer.from(image.uint8Array)
    } else if (image.base64) {
      buffer = Buffer.from(image.base64, IMAGE_BASE64_ENCODING)
    }

    if (!buffer || buffer.length === 0) {
      throw new Error("[ai-edit-image] Empty image payload from provider")
    }

    if (buffer.length > MAX_IMAGE_BYTES) {
      throw new Error(`[ai-edit-image] Image too large: ${buffer.length} bytes`)
    }

    const contentType = image.mediaType || IMAGE_DEFAULT_MIME_TYPE
    const rawExt = contentType.split("/")[1]?.split(";")[0]?.trim() ?? ""
    const extension = ALLOWED_IMAGE_EXTENSIONS.has(rawExt)
      ? rawExt
      : IMAGE_DEFAULT_EXTENSION

    const executionId = metadata?.stepId ?? step.id
    const fileName = `${executionId}.${extension}`
    const storagePath = getAIGeneratedImagePath({
      storagePrefix: ctx.storagePrefix,
      fileName,
      conversationId: conversation.id,
    })

    await ctx.uploader.putObject(storagePath, buffer, {
      ContentType: contentType,
    })

    const { storageUrl } = await resolveTenantSettings({
      workspaceId: conversation.workspaceId,
    })
    const finalImageUrl = getPublicFileUrl(storagePath, storageUrl)

    if (step.outputFieldId) {
      await saveResultToCustomField({
        contactId: conversation.contactId,
        customFieldId: step.outputFieldId,
        fullText: finalImageUrl,
        workspaceId: conversation.workspaceId,
      })
    }

    return { status: "success", result: null }
  } catch (err) {
    const error = normalizeError(err)
    logger.error(
      {
        err: error,
        workspaceId: conversation.workspaceId,
        conversationId: conversation.id,
        action: "aiEditImage",
      },
      "[ai-edit-image] Step failed",
    )
    return { status: "error", errorMessage: error.message, result: null }
  } finally {
    clearTimeout(timeoutId)
  }
}

import { aiProviders, aiTimeouts } from "@openmeerkat/ai"
import {
  aiIntegrationService,
  createAIImageModelInstance,
} from "@openmeerkat/ai/server"
import { resolveTenantSettings } from "@openmeerkat/business"
import { getPublicFileUrl } from "@openmeerkat/business/utils"
import {
  type AIGenerateImageQualityType,
  type AIGenerateImageSchema,
  getAIGeneratedImagePath,
  IMAGE_AUTO_VALUE,
  IMAGE_BASE64_ENCODING,
  IMAGE_DEFAULT_EXTENSION,
  IMAGE_DEFAULT_MIME_TYPE,
} from "@openmeerkat/flow-config"
import { generateImage } from "ai"
import { normalizeError } from "universal-error-normalizer"
import { logger } from "../../../lib/logger"
import {
  getIntegrationContext,
  saveResultToCustomField,
} from "../../utils/contact"
import type { ExecuteStepProps } from "../flow"
import type { ExecuteStepResult } from "../step"

const MAX_IMAGE_BYTES = 10 * 1024 * 1024
const ALLOWED_EXTENSIONS = new Set(["png", "jpg", "jpeg", "webp", "gif"])
const GPT_IMAGE_QUALITY_MAP: Record<
  AIGenerateImageQualityType,
  "auto" | "high" | "medium" | "low"
> = {
  auto: "auto",
  hd: "high",
  md: "medium",
  ld: "low",
}

const DALL_E_QUALITY_MAP: Record<
  AIGenerateImageQualityType,
  "auto" | "hd" | "standard"
> = {
  auto: "auto",
  hd: "hd",
  md: "standard",
  ld: "standard",
}

function getOpenAIImageQuality(
  modelId: string,
  quality: AIGenerateImageQualityType,
) {
  return modelId.startsWith("gpt-image") || modelId.startsWith("chatgpt-image")
    ? GPT_IMAGE_QUALITY_MAP[quality]
    : DALL_E_QUALITY_MAP[quality]
}

export async function handleAIGenerateImage({
  conversation,
  contactInbox: baseContactInbox,
  metadata,
  step,
}: ExecuteStepProps<AIGenerateImageSchema>): Promise<ExecuteStepResult> {
  const controller = new AbortController()
  const timeoutId = setTimeout(() => controller.abort(), aiTimeouts.aiTotal)

  try {
    const aiConfig = await aiIntegrationService.findBy({
      workspaceId: conversation.workspaceId,
      provider: step.provider,
    })

    if (!aiConfig) {
      return {
        status: "error",
        errorMessage: "AI integration not found",
        result: null,
      }
    }

    const ctx = await getIntegrationContext({
      workspaceId: conversation.workspaceId,
      contactId: conversation.contactId,
      contactInbox: baseContactInbox,
    })

    if (!ctx) {
      logger.warn(
        {
          workspaceId: conversation.workspaceId,
          conversationId: conversation.id,
        },
        "[ai-generate-image] Integration context not found, skipping",
      )
      return {
        status: "error",
        errorMessage: "Integration context not found",
        result: null,
      }
    }

    let buffer: Buffer | null = null

    const modelId = step.model

    const model = createAIImageModelInstance({
      model: aiConfig,
      provider: step.provider,
      modelId,
    })

    const size =
      step.provider === aiProviders.enum.openai &&
      step.size !== IMAGE_AUTO_VALUE
        ? (step.size as `${number}x${number}`)
        : undefined

    const aspectRatio =
      step.provider === aiProviders.enum.gemini &&
      step.size !== IMAGE_AUTO_VALUE
        ? (step.size as `${number}:${number}`)
        : undefined

    const providerOptions =
      step.provider === aiProviders.enum.openai && step.quality !== "auto"
        ? {
            openai: {
              quality: getOpenAIImageQuality(modelId, step.quality),
            },
          }
        : undefined

    const { image } = await generateImage({
      model,
      prompt: step.prompt,
      size,
      aspectRatio,
      providerOptions,
      abortSignal: controller.signal,
    })

    if (image.uint8Array && image.uint8Array.byteLength > 0) {
      buffer = Buffer.from(image.uint8Array)
    } else if (image.base64) {
      buffer = Buffer.from(image.base64, IMAGE_BASE64_ENCODING)
    }

    const contentType = image.mediaType || IMAGE_DEFAULT_MIME_TYPE

    if (!buffer || buffer.length === 0) {
      throw new Error("[ai-generate-image] Empty image payload from provider")
    }

    if (buffer.length > MAX_IMAGE_BYTES) {
      throw new Error(
        `[ai-generate-image] Image too large: ${buffer.length} bytes`,
      )
    }

    const rawExt = contentType.split("/")[1]?.split(";")[0]?.trim() ?? ""
    const extension = ALLOWED_EXTENSIONS.has(rawExt)
      ? rawExt
      : IMAGE_DEFAULT_EXTENSION

    // Use a deterministic execution ID so BullMQ retries overwrite the same
    // S3 object instead of orphaning the previously uploaded file.
    const executionId = metadata?.stepId ?? step.id
    const fileName = `${executionId}.${extension}`
    const storagePath = getAIGeneratedImagePath({
      storagePrefix: ctx.storagePrefix,
      fileName,
      conversationId: conversation.id,
    })

    await ctx.uploader.putObject(storagePath, buffer, {
      ContentType: contentType,
    })

    const { storageUrl } = await resolveTenantSettings({
      workspaceId: conversation.workspaceId,
    })
    const finalImageUrl = getPublicFileUrl(storagePath, storageUrl)

    if (step.outputFieldId) {
      await saveResultToCustomField({
        contactId: conversation.contactId,
        customFieldId: step.outputFieldId,
        fullText: finalImageUrl,
        workspaceId: conversation.workspaceId,
      })
    }

    return { status: "success", result: null }
  } catch (err) {
    const error = normalizeError(err)
    logger.error(
      {
        err: error,
        workspaceId: conversation.workspaceId,
        conversationId: conversation.id,
      },
      "[ai-generate-image] Step failed",
    )
    return { status: "error", errorMessage: error.message, result: null }
  } finally {
    clearTimeout(timeoutId)
  }
}

#!/bin/sh

# --enable-source-maps resolves production stack traces back to original TypeScript source.
NODE_OPTIONS="--no-node-snapshot --enable-source-maps" HOSTNAME=${HOSTNAME:-0.0.0.0} PORT=${PORT:-3000} node apps/mcp-server/dist/index.mjs;

import { readFileSync } from "node:fs"
import { join } from "node:path"
import { describe, expect, test } from "vitest"

const drizzleDir = join(import.meta.dirname, "../drizzle")

const contactOnBroadcastSql = readFileSync(
  join(
    drizzleDir,
    "20260612235000_partition_contact_on_broadcast/migration.sql",
  ),
  "utf8",
)

const sequenceSql = readFileSync(
  join(
    drizzleDir,
    "20260612235500_partition_contact_on_sequence_and_dispatch/migration.sql",
  ),
  "utf8",
)

function insertColumns(sql: string, tableName: string) {
  const match = new RegExp(
    `INSERT INTO "${tableName}" \\((?<columns>[\\s\\S]*?)\\)\\s*SELECT`,
  ).exec(sql)

  if (!match?.groups?.columns) {
    throw new Error(`Missing INSERT column list for ${tableName}`)
  }

  return match.groups.columns
}

describe("partition migrations", () => {
  test("ContactOnBroadcast copy uses explicit columns and excludes generated isRead", () => {
    expect(contactOnBroadcastSql).not.toContain("SELECT *")

    const columns = insertColumns(
      contactOnBroadcastSql,
      "ContactOnBroadcast_new",
    )
    expect(columns).toContain('"broadcastId"')
    expect(columns).toContain('"sent"')
    expect(columns).not.toContain('"isRead"')
  })

  test("SequenceDispatch copy excludes generated isRead and stale ContactOnSequence columns", () => {
    expect(sequenceSql).not.toContain("SELECT *")

    const dispatchColumns = insertColumns(sequenceSql, "SequenceDispatch_new")
    expect(dispatchColumns).toContain('"status"')
    expect(dispatchColumns).toContain('"workspaceId"')
    expect(dispatchColumns).not.toContain('"isRead"')

    const enrollmentColumns = insertColumns(
      sequenceSql,
      "ContactOnSequence_new",
    )
    expect(enrollmentColumns).not.toContain('"errorCount"')
  })

  test("validates new partitioned tables before irreversible drops", () => {
    const broadcastValidation = contactOnBroadcastSql.indexOf(
      "ContactOnBroadcast_new expected 64 partitions",
    )
    const broadcastDrop = contactOnBroadcastSql.indexOf(
      'DROP TABLE "ContactOnBroadcast_old"',
    )
    expect(broadcastValidation).toBeGreaterThanOrEqual(0)
    expect(broadcastValidation).toBeLessThan(broadcastDrop)

    const sequenceValidation = sequenceSql.indexOf(
      "SequenceDispatch_new expected 64 partitions",
    )
    const sequenceDrop = sequenceSql.indexOf(
      'DROP TABLE "SequenceDispatch_old"',
    )
    expect(sequenceValidation).toBeGreaterThanOrEqual(0)
    expect(sequenceValidation).toBeLessThan(sequenceDrop)
  })

  test("SequenceDispatch uses workspace hash partitioning without idempotency registry", () => {
    expect(sequenceSql).toContain(
      'CONSTRAINT "SequenceDispatch_new_pkey" PRIMARY KEY ("id", "workspaceId")',
    )
    expect(sequenceSql).toContain('PARTITION BY HASH ("workspaceId")')
    expect(sequenceSql).toContain(
      'CREATE UNIQUE INDEX "SequenceDispatch_idempotencyKey_key_new"',
    )
    expect(sequenceSql).toContain(
      'ON "SequenceDispatch_new" ("idempotencyKey", "workspaceId")',
    )
    expect(sequenceSql).toContain(
      'CREATE INDEX "SequenceDispatch_pending_runAtMs_idx_new"',
    )
    expect(sequenceSql).toContain(
      'CREATE INDEX "SequenceDispatch_pending_bucket_runAtMs_idx_new"',
    )
    expect(sequenceSql).not.toContain('PARTITION BY LIST ("status")')
    expect(sequenceSql).not.toContain('"SequenceDispatchIdempotency"')
  })
})

