import { Button } from "@openmeerkat/ui/components/ui/button"
import { ImageIcon, XIcon } from "lucide-react"
import Image from "next/image"
import { useTranslations } from "next-intl"
import { type MouseEvent, useEffect, useState } from "react"
import Dropzone from "react-dropzone"

function AttachedImage({
  image,
  onRemove,
}: {
  image: string
  onRemove: () => void
}) {
  const onClick = (e: MouseEvent) => {
    e.stopPropagation()
    onRemove()
  }

  return (
    <div className="relative h-full w-full">
      <Image
        alt="Uploaded Image"
        className="object-contain"
        fill={true}
        src={image}
      />
      <Button
        className="absolute end-0 top-0 hover:bg-transparent"
        onClick={onClick}
        variant="ghost"
      >
        <XIcon />
      </Button>
    </div>
  )
}

function NeedAttachedImage({
  onSwitchToImageLink,
}: {
  onSwitchToImageLink: () => void
}) {
  const t = useTranslations()

  const switchToImageLinkMode = (e: MouseEvent) => {
    e.stopPropagation()
    onSwitchToImageLink()
  }

  return (
    <>
      <div className="p-4 pt-0">
        <ImageIcon />
      </div>
      <div>
        {t("texts.or")}
        {"\u00A0"}
        <Button
          className="p-0 text-destructive"
          onClick={switchToImageLinkMode}
          variant="link"
        >
          {t("actions.insertLink")}
        </Button>
      </div>
    </>
  )
}

export default function ImageDropzone({
  oldImage,
  onSwitchToImageLink,
  onChange,
}: {
  oldImage: Record<string, unknown>
  onSwitchToImageLink: () => void
  onChange: (file?: Record<string, unknown>) => void
}) {
  const [image, setImage] = useState<string | null>(null)

  const handleFileChange = (file: File | null) => {
    if (file) {
      const reader = new FileReader()
      reader.onloadend = () => {
        setImage(reader.result as string)
        onChange({ file, base64: reader.result })
      }
      reader.readAsDataURL(file)
    }
  }

  const handleRemove = () => {
    setImage(null)
    onChange({ file: null, base64: null })
  }

  useEffect(() => {
    if (oldImage && Object.keys(oldImage)) {
      setImage(oldImage.base64 as string)
    }
  }, [oldImage])

  return (
    <Dropzone
      accept={{ "image/*": [] }}
      maxFiles={1}
      onDrop={(acceptedFiles) => handleFileChange(acceptedFiles[0] ?? null)}
    >
      {({ getRootProps, getInputProps }) => (
        <section>
          <div {...getRootProps()}>
            <input {...getInputProps()} />
            <div className="flex h-36 flex-col items-center justify-center overflow-hidden rounded-lg border-2 border-dashed hover:cursor-pointer hover:border-blue-500 hover:border-solid">
              {image ? (
                <AttachedImage image={image} onRemove={handleRemove} />
              ) : (
                <NeedAttachedImage onSwitchToImageLink={onSwitchToImageLink} />
              )}
            </div>
          </div>
        </section>
      )}
    </Dropzone>
  )
}

import type { Context } from "@openmeerkat/sdk"
import { createId } from "@openmeerkat/utils"
import type { ZaloAuthValue } from "../schema/definition"

export const fetchAndReuploadImage = async ({
  ctx,
  avatarUrl,
}: {
  ctx: Context<ZaloAuthValue>
  avatarUrl: string
}): Promise<string | undefined> => {
  const response = await fetch(avatarUrl, {
    headers: {
      Authorization: `Bearer ${ctx.auth.tokens.accessToken}`,
      "User-Agent": "node",
    },
  })
  if (response.ok && response.body) {
    const originPath = `${ctx.storagePrefix}/${createId()}`
    const bytes = await response.arrayBuffer()
    const mimeType = response.headers.get("content-type") ?? "image/png"

    await ctx.uploader?.putObject(originPath, Buffer.from(bytes), {
      ACL: "public-read",
      ContentType: mimeType,
    })

    return originPath
  }
}

import { createId, zodBigintAsString } from "@openmeerkat/utils"
import { z } from "zod"

import {
  errorStateDefaultFn,
  errorStateSchema,
  successStateDefaultFn,
  successStateSchema,
} from "../states"
import { stepTypes } from "./step-action"

export const aiAnalyzeImageProvider = z.enum([
  "openai",
  "gemini",
  "claude",
  "openrouter",
])
export type AIAnalyzeImageProvider = z.infer<typeof aiAnalyzeImageProvider>
export const aiAnalyzeImageProviderSchema = z.enum([
  ...aiAnalyzeImageProvider.options,
  "openaiCompatible",
])

export const defaultAnalyzeModels = {
  openai: "gpt-5.4-mini",
  gemini: "gemini-3.5-flash",
  claude: "claude-haiku-4-5-20251001",
  openrouter: "openai/gpt-5.4-mini",
} as const

export const aiAnalyzeImageSchema = z
  .object({
    id: zodBigintAsString(),
    stepType: z.literal(stepTypes.enum.aiAnalyzeImage),
    provider: aiAnalyzeImageProviderSchema,
    integrationId: z.string().trim().optional(),
    model: z.string().trim(),
    prompt: z.string().trim().min(1),
    inputFieldId: z.string().trim().min(1),
    outputFieldId: z.string().trim().min(1),
    temperature: z.number().min(0).max(2),
    maxOutputTokens: z.number().int().min(250).max(4096),
    states: z.tuple([successStateSchema, errorStateSchema]).optional(),
  })
  .superRefine((value, ctx) => {
    if (!value.model.trim()) {
      ctx.addIssue({
        code: "custom",
        path: ["model"],
        message: "Model is required",
      })
    }
    if (value.provider === "openaiCompatible" && !value.integrationId?.trim()) {
      ctx.addIssue({
        code: "custom",
        path: ["integrationId"],
        message: "Integration is required",
      })
    }
  })

export type AIAnalyzeImageSchema = z.infer<typeof aiAnalyzeImageSchema>

export const AIAnalyzeImageDefaultFn = (
  props: Partial<AIAnalyzeImageSchema> = {},
): AIAnalyzeImageSchema => {
  const provider = props.provider ?? "openai"
  const model: string =
    props.model ??
    (provider === "openaiCompatible"
      ? ""
      : defaultAnalyzeModels[provider as keyof typeof defaultAnalyzeModels])

  return {
    id: createId(),
    provider,
    ...(provider === "openaiCompatible"
      ? { integrationId: "integrationId" in props ? props.integrationId : "" }
      : {}),
    model,
    prompt: "",
    inputFieldId: "",
    outputFieldId: "",
    temperature: 1.0,
    maxOutputTokens: 1000,
    ...props,
    stepType: stepTypes.enum.aiAnalyzeImage,
    states: [successStateDefaultFn(), errorStateDefaultFn()],
  }
}

